import React, { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import MainNav from "../../MainNav/MainNav";

const BASE_URL = "http://localhost:5000/registeredArtists";

const ArtistLogin = () => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post(`${BASE_URL}/login`, { email, password });
      const artist = res.data.artist;

      // Save artist info locally (session/local storage)
      localStorage.setItem("artistId", artist.id);
      localStorage.setItem("artistName", artist.stageName);

      // Navigate to portfolio
      navigate(`/portfolio/${artist.id}`);
    } catch (err) {
      alert(err.response?.data?.message || "Login failed");
    }
  };

  return (
    <div className="login-container">
        <MainNav/>
      <h2>Artist Login</h2>
      <form onSubmit={handleLogin}>
        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
        />
        <input
          type="password"
          placeholder="Password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
        />
        <button type="submit">Login</button>
      </form>
    </div>
  );
};

export default ArtistLogin;
